import unittest
from pkg.config import config_value
import random
import string

class TestConfigValue(unittest.TestCase):
    def test_fuzz(self):
        random.seed(1234)
        for _ in range(500):
            key = ''.join(random.choices(string.ascii_letters, k=random.randint(1, 10)))
            config = {k: v for k, v in zip(random.sample(range(100), random.randint(1, 99)), \
                                           [random.randint(-1000, 1000) for _ in range(random.randint(1, 99))])}
            self.assertIsNone(config_value(config, key))
if __name__ == '__main__':
    unittest.main()

